async function refreshItems(){if(state.demo){state.items=loadJson(DEMO_KEY,[])||[];state.loading=false;state.error='';renderSelectionAndList();status('',STATUS_TEXT.demoTitle,STATUS_TEXT.demoDetail);return}if(!state.entity)return;try{const result=await todoList(),incoming=Array.isArray(result?.items)?result.items:[];state.items=incoming.filter(item=>!state.pendingRemoval.has(norm(itemSummary(item))));state.loading=false;state.error='';syncProductSelection();if(!listDomMatchesCurrentState())renderList();status('','Synchronisé',state.entities.find(e=>e.id===state.entity)?.name||state.entity)}catch(error){state.loading=false;state.error=error.message||'Liste Courses indisponible';renderList();status('is-error','Courses indisponible',state.error)}}async function incrementProduct(name){const item=String(name||'').trim();if(!item)return;const key=norm(item);if(state.productBusy.has(key))return;const current=activeGroups().find(group=>norm(group.summary)===key)?.count||0;state.productBusy.add(key);setProductQuantity(item,current+1);try{await addItem(item)}finally{state.productBusy.delete(key);renderSelectionAndList()}}async function decrementProduct(name){const item=String(name||'').trim();if(!item)return;const key=norm(item);if(state.productBusy.has(key))return;const group=activeGroups().find(entry=>norm(entry.summary)===key);if(!group||group.count<1)return;state.productBusy.add(key);setProductQuantity(item,group.count-1);try{await removeOneItem(item,group)}finally{state.productBusy.delete(key);renderSelectionAndList()}}async function addItem(name){const item=String(name||'').trim();if(!item)return;if(state.demo){const items=loadJson(DEMO_KEY,[])||[];items.push({uid:'demo-'+Date.now()+'-'+Math.random().toString(36).slice(2),summary:item,status:'needs_action'});saveJson(DEMO_KEY,items);state.items=items;recordUsage(item);navigator.vibrate?.(10);toast(item+' ajouté');renderSelectionAndList();return}if(!state.entity)return;try{await todoService('add_item',{item});recordUsage(item);navigator.vibrate?.(10);toast(item+' ajouté');await refreshItems()}catch(error){toast('Ajout impossible');status('is-error','Erreur',error.message||'Ajout impossible')}}async function completeTodoItem(uid){const uidValue=String(uid||'').trim();if(!uidValue)throw new Error('Identifiant de l’article indisponible');return todoService('update_item',{item:uidValue,status:'completed'})}async function removeOneItem(name,groupHint=null){const item=String(name||'').trim();if(!item)return;const key=norm(item),group=groupHint||activeGroups().find(entry=>norm(entry.summary)===key);if(!group||group.count<1)return;try{if(state.demo){const items=loadJson(DEMO_KEY,[])||[];let removeIndex=-1;for(let i=items.length-1;i>=0;i--){const entry=items[i];if(!isPendingItem(entry))continue;if(norm(itemSummary(entry))===key){removeIndex=i;break}}if(removeIndex<0)return;items.splice(removeIndex,1);saveJson(DEMO_KEY,items);state.items=items;navigator.vibrate?.(8);toast(item+' -1');renderSelectionAndList();return}if(!state.entity)throw new Error('Liste Home Assistant indisponible');const uid=group.uids.filter(Boolean).at(-1);await completeTodoItem(uid);navigator.vibrate?.(8);toast(item+' -1');await refreshItems()}catch(error){toast('Retrait impossible');status('is-error','Erreur',error.message||'Retrait impossible')}}
