async function init(){renderView();if(!window.crypto?.subtle){state.loading=false;renderList();showSetup('Ce navigateur ne prend pas en charge le chiffrement Web Crypto requis.');status('is-error','Navigateur incompatible','Web Crypto indisponible');return}deleteKey(LEGACY_UNLOCK_KEY);const params=new URLSearchParams(location.search),code=params.get('code');if(code){const oauth=loadOAuthState(),returnedState=params.get('state')||'';if(!oauth||oauth.nonce!==returnedState||!normalizeHaUrl(oauth.haUrl)){history.replaceState({},'',REDIRECT_URI);showSetup('Retour OAuth invalide ou expiré. Recommence la connexion.');return}state.haUrl=normalizeHaUrl(oauth.haUrl);state.pendingOAuthCode=code;state.pendingOAuthState=returnedState;history.replaceState({},'',REDIRECT_URI);state.loading=false;renderList();showSecurity('oauth','Crée maintenant le mot de passe local qui protégera l’autorisation Home Assistant sur cet appareil.');status('is-waiting','Sécurisation requise','Créer le mot de passe local');return}const legacy=legacyAuthRecord();if(legacy?.refresh_token){state.haUrl=normalizeHaUrl(legacy.ha_url||localStorage.getItem(STORAGE.haUrl)||'');state.loading=false;renderList();showSecurity('migrate','Une ancienne connexion non chiffrée a été détectée. Crée un mot de passe local pour la chiffrer immédiatement.');status('is-waiting','Migration sécurité','Chiffrement de la connexion');return}if(vaultRecord()){state.loading=false;renderList();showSecurity('unlock');status('is-waiting',STATUS_TEXT.lockedTitle,STATUS_TEXT.passwordRequired);return}state.haUrl=normalizeHaUrl(localStorage.getItem(STORAGE.haUrl)||'');state.loading=false;renderView();showSetup();status('is-waiting','Configuration requise','Première connexion')}
